using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace MyscotekDataCopier
{
	// Entry point XrmToolBox discovers via MEF (Lazy<IXrmToolBoxPlugin, IPluginMetadata>).
	// IPluginMetadata has no [DefaultValue]s, so EVERY one of the seven ExportMetadata keys below
	// must be present - if any is missing the export is silently dropped and the tool never shows.
	[Export(typeof(IXrmToolBoxPlugin))]
	[ExportMetadata("Name", "Data Copier")]
	[ExportMetadata("Description", "Copies selected records from a source to a destination Dataverse / Dynamics 365 environment keeping the same GUIDs, with the records their lookups point at and, optionally, their child records and N:N associations.")]
	[ExportMetadata("BackgroundColor", "#2868B1")]
	[ExportMetadata("PrimaryFontColor", "White")]
	[ExportMetadata("SecondaryFontColor", "WhiteSmoke")]
	[ExportMetadata("SmallImageBase64", PluginImages.Small)]
	[ExportMetadata("BigImageBase64", PluginImages.Big)]
	public class MyscotekDataCopierPlugin : PluginBase
	{
		public override IXrmToolBoxPluginControl GetControl() => new UI.DataCopierControl();
	}

	// Base64-encoded PNG tiles shown by XrmToolBox: Small (32x32) in the small tools list, Big (120x120)
	// on the large tiles - the Myscotek logo. Held as const strings so they can be [ExportMetadata]
	// attribute arguments. Never edit by hand; images\icon-*.png (repository, NuGet icon) are made from them.
	internal static class PluginImages
	{
		internal const string Small = "";
		internal const string Big = "";
	}
}
